    private static OperationContract ContractFor(SellAppRequest request) => Contracts.FirstOrDefault(c => c.Method == request.Method.Method && c.Path.Split('/').Length == request.Path.Split('/').Length && c.Path.Split('/').Zip(request.Path.Split('/')).All(pair => pair.First.StartsWith("{") || pair.First == pair.Second)) ?? new(request.Method.Method, request.Path, false, true, false, false, false, false, true, true, false, "", false, false, false, "[]", []);
    public Uri BuildRequestUri(SellAppRequest request) => BuildMessage(request).RequestUri!;
    private string ValidateRelativePath(string path)
    {
        if (string.IsNullOrWhiteSpace(path) || path.StartsWith("//", StringComparison.Ordinal)
            || (!path.StartsWith("/", StringComparison.Ordinal) && Uri.TryCreate(path, UriKind.Absolute, out _)))
            throw new ConfigurationException("Request path must be relative to the configured API origin.");
        if (!Uri.TryCreate(baseAddress, path.TrimStart('/'), out var resolved)
            || !string.Equals(resolved.Scheme, baseAddress!.Scheme, StringComparison.OrdinalIgnoreCase)
            || !string.Equals(resolved.Host, baseAddress.Host, StringComparison.OrdinalIgnoreCase)
            || resolved.Port != baseAddress.Port || !string.IsNullOrEmpty(resolved.UserInfo)
            || !string.IsNullOrEmpty(resolved.Fragment))
            throw new ConfigurationException("Request path must stay on the configured API origin and contain no credentials or fragment.");
        return path.TrimStart('/');
    }

    internal int ValidateNextPage(string path, string link)
    {
        if (!Uri.TryCreate(baseAddress, path.TrimStart('/'), out var current) || !Uri.TryCreate(current, link, out var next))
            throw new SerializationException("Malformed pagination link.");
        if (!string.Equals(current.Scheme, next.Scheme, StringComparison.OrdinalIgnoreCase)
            || !string.Equals(current.Host, next.Host, StringComparison.OrdinalIgnoreCase)
            || current.Port != next.Port || current.AbsolutePath != next.AbsolutePath
            || !string.IsNullOrEmpty(next.UserInfo) || !string.IsNullOrEmpty(next.Fragment))
            throw new SerializationException("Unsafe pagination link rejected.");
        var values = next.Query.TrimStart('?').Split('&', StringSplitOptions.RemoveEmptyEntries)
            .Select(part => part.Split('=', 2)).Where(part => Uri.UnescapeDataString(part[0]) == "page").ToList();
        if (values.Count != 1 || values[0].Length != 2 || !int.TryParse(Uri.UnescapeDataString(values[0][1]), out var page) || page <= 0)
            throw new SerializationException("Pagination link must contain one positive page value.");
        return page;
    }

    public async Task<T> MakeAPIRequest<T>(SellAppRequest request, CancellationToken cancellationToken = default) =>
        (await MakeAPIRequestWithResponse<T>(request, cancellationToken).ConfigureAwait(false)).Value;

    public async Task<ApiResponse<T>> MakeAPIRequestWithResponse<T>(SellAppRequest request, CancellationToken cancellationToken = default)
    {
        using var response = await SendAsync(request, cancellationToken).ConfigureAwait(false);
        var content = await response.Content.ReadAsStringAsync(cancellationToken).ConfigureAwait(false);
        try
        {
            var declaredText = ContractFor(request).TextResponses.Where(t => t.StartsWith(((int)response.StatusCode).ToString() + ":", StringComparison.Ordinal)).Select(t => t[(t.IndexOf(':') + 1)..]).ToArray();
            var mediaType = response.Content.Headers.ContentType?.MediaType;
            var isText = typeof(T) == typeof(string) && declaredText.Length > 0 && ((content.Length == 0 && declaredText.Contains("")) || mediaType is null || declaredText.Contains(mediaType, StringComparer.OrdinalIgnoreCase));
            var value = isText ? (T)(object)content : JsonConvert.DeserializeObject<T>(content, JsonSettings) ?? throw new JsonException("Empty response.");
            SellAppSchemaValidation.ValidateResponse(value);
            var headers = response.Headers.Concat(response.Content.Headers).ToDictionary(h => h.Key, h => h.Value.ToArray(), StringComparer.OrdinalIgnoreCase);
            var requestId = headers.TryGetValue("X-Request-ID", out var ids) ? ids.FirstOrDefault() : null;
            if (request.RequestOptions?.Capture is { } capture) { capture.Status = (int)response.StatusCode; capture.Headers = headers; capture.RequestId = requestId; capture.RawBody = content; }
            return new ApiResponse<T> { Value = value, Status = (int)response.StatusCode, Headers = headers, RequestId = requestId, RawBody = content };
        }
        catch (Exception ex) when (ex is JsonException) { throw new SerializationException("Unable to deserialize the API response.", ex); }
    }

    public async Task MakeRawAPIRequest(SellAppRequest request, CancellationToken cancellationToken = default)
    {
        using var response = await SendAsync(request, cancellationToken).ConfigureAwait(false);
        var raw = await response.Content.ReadAsStringAsync(cancellationToken).ConfigureAwait(false);
        var headers = response.Headers.Concat(response.Content.Headers).ToDictionary(h => h.Key, h => h.Value.ToArray(), StringComparer.OrdinalIgnoreCase);
        var requestId = headers.TryGetValue("X-Request-ID", out var ids) ? ids.FirstOrDefault() : null;
        if (request.RequestOptions?.Capture is { } capture) { capture.Status = (int)response.StatusCode; capture.Headers = headers; capture.RequestId = requestId; capture.RawBody = raw; }
    }

    private async Task<HttpResponseMessage> SendAsync(SellAppRequest request, CancellationToken cancellationToken)
    {
        var retries = request.RequestOptions?.MaxRetries ?? maxRetries;
        if (retries < 0) throw new ConfigurationException("MaxRetries must be non-negative.");
        if (request.RequestOptions?.Timeout is { } configuredTimeout && configuredTimeout <= TimeSpan.Zero) throw new ConfigurationException("Timeout must be positive.");
        if (!string.IsNullOrWhiteSpace(request.RequestOptions?.IdempotencyKey) && request.RequestOptions?.SupportsIdempotency != true) throw new ConfigurationException("This operation does not declare Idempotency-Key support.");
        var contract = ContractFor(request);
        var replayable = !contract.NeverRetry && !contract.CustomerSession && (request.Method == HttpMethod.Get || request.Method == HttpMethod.Head || request.Method == HttpMethod.Options || request.Method == HttpMethod.Put || request.Method == HttpMethod.Delete || request.RequestOptions?.SupportsIdempotency == true && !string.IsNullOrWhiteSpace(request.RequestOptions.IdempotencyKey));
        for (var attempt = 0; ; attempt++)
        {
            var started = System.Diagnostics.Stopwatch.StartNew();
            try
            {
                using var message = BuildMessage(request);
                using var timeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
                timeout.CancelAfter(request.RequestOptions?.Timeout ?? defaultTimeout);
                var response = await http.SendAsync(message, timeout.Token).ConfigureAwait(false);
                var requestId = response.Headers.TryGetValues("X-Request-ID", out var requestIds) ? requestIds.FirstOrDefault() : null;
                if ((int)response.StatusCode >= 200 && (int)response.StatusCode < 400) { onRequest?.Invoke(new RequestEvent { OperationId = request.RequestOptions?.OperationId ?? string.Empty, Attempt = attempt + 1, Duration = started.Elapsed, Status = (int)response.StatusCode, RequestId = requestId }); return response; }
                if (replayable && attempt < retries && IsRetryable(response.StatusCode))
                {
                    onRequest?.Invoke(new RequestEvent { OperationId = request.RequestOptions?.OperationId ?? string.Empty, Attempt = attempt + 1, Duration = started.Elapsed, Status = (int)response.StatusCode, RequestId = requestId, ErrorType = "retry" });
                    var delay = RetryDelay(response, attempt);
                    response.Dispose();
                    await Task.Delay(delay, cancellationToken).ConfigureAwait(false);
                    continue;
                }
                onRequest?.Invoke(new RequestEvent { OperationId = request.RequestOptions?.OperationId ?? string.Empty, Attempt = attempt + 1, Duration = started.Elapsed, Status = (int)response.StatusCode, RequestId = requestId, ErrorType = "api" });
                await ThrowApiException(response, cancellationToken).ConfigureAwait(false);
            }
            catch (TaskCanceledException ex) when (!cancellationToken.IsCancellationRequested)
            {
                onRequest?.Invoke(new RequestEvent { OperationId = request.RequestOptions?.OperationId ?? string.Empty, Attempt = attempt + 1, Duration = started.Elapsed, ErrorType = "timeout" });
                throw new SellAppTimeoutException("The SellApp request timed out.", ex);
            }
            catch (HttpRequestException ex)
            {
                if (!replayable || attempt >= retries) { onRequest?.Invoke(new RequestEvent { OperationId = request.RequestOptions?.OperationId ?? string.Empty, Attempt = attempt + 1, Duration = started.Elapsed, ErrorType = "transport" }); throw new TransportException("The SellApp request failed.", ex); }
                onRequest?.Invoke(new RequestEvent { OperationId = request.RequestOptions?.OperationId ?? string.Empty, Attempt = attempt + 1, Duration = started.Elapsed, ErrorType = "retry" });
                await Task.Delay(RetryDelay(null, attempt), cancellationToken).ConfigureAwait(false);
            }
        }
    }

    private HttpRequestMessage BuildMessage(SellAppRequest request)
    {
        var contract = ContractFor(request);
        string? authorization = null; string? selectedStore = null; string? cookie = null;
        var session = request.RequestOptions?.CustomerSession ?? customerSession;
        var oauth = request.AccessToken ?? accessToken;
        if (contract.CustomerSession && !string.IsNullOrWhiteSpace(session)) authorization = "Bearer " + session;
        else if (contract.AccessToken && !string.IsNullOrWhiteSpace(oauth)) { if (contract.AccessTokenStore && string.IsNullOrWhiteSpace(store)) throw new ConfigurationException("Store is required for OAuth."); authorization = "Bearer " + oauth; selectedStore = contract.AccessTokenStore ? store : null; }
        else if (contract.ApiKey && !string.IsNullOrWhiteSpace(apiKey)) { if (contract.ApiKeyStore && string.IsNullOrWhiteSpace(store)) throw new ConfigurationException("Store is required."); authorization = "Bearer " + apiKey; selectedStore = contract.ApiKeyUsesStore ? store : null; }
        else if (contract.BrowserSession && !string.IsNullOrWhiteSpace(browserSession)) cookie = browserSession;
        else if (contract.ClientBasic && !string.IsNullOrWhiteSpace(clientId)) authorization = "Basic " + Convert.ToBase64String(Encoding.UTF8.GetBytes(WebUtility.UrlEncode(clientId) + ":" + WebUtility.UrlEncode(clientSecret ?? "")));
        else if (!contract.Anonymous) throw new ConfigurationException("Credentials required by this operation are missing.");
        var requestBody = request.Options is IUnionRequestOptions unionOptions ? unionOptions.RequestBody : request.Options;
        SellAppSchemaValidation.ValidateRequest(requestBody);
        var serializer = JsonSerializer.Create(JsonSettings);
        var values = requestBody is null ? new JObject() : JObject.FromObject(requestBody, serializer);
        if (request.QueryParams is not null) foreach (var pair in request.QueryParams) values[pair.Key] = pair.Value is null ? null : JToken.FromObject(pair.Value);
        var path = ValidateRelativePath(request.Path);
        if (request.Method == HttpMethod.Get || request.Method == HttpMethod.Delete && !contract.Form)
        {
            var query = string.Join("&", values.Properties().Where(p => p.Value.Type != JTokenType.Null).Select(p => $"{Uri.EscapeDataString(p.Name)}={Uri.EscapeDataString(p.Value.ToString())}"));
            if (query.Length > 0) path += (path.Contains('?') ? "&" : "?") + query;
        }
        if (contract.Server.Length > 0) path = (customBase ? baseAddress!.GetLeftPart(UriPartial.Authority) : contract.Server).TrimEnd('/') + "/" + path;
        var message = new HttpRequestMessage(request.Method, new Uri(baseAddress, path));
        message.Headers.UserAgent.ParseAdd("sellapp-dotnet/0.1.0");
        if (!string.IsNullOrWhiteSpace(request.RequestOptions?.IdempotencyKey)) message.Headers.Add("Idempotency-Key", request.RequestOptions.IdempotencyKey);
        if (request.RequestOptions?.Headers is not null) foreach (var header in request.RequestOptions.Headers) message.Headers.TryAddWithoutValidation(header.Key, header.Value);
        message.Headers.Remove("Authorization"); message.Headers.Remove("X-STORE"); message.Headers.Remove("Cookie");
        if (authorization is not null) message.Headers.TryAddWithoutValidation("Authorization", authorization);
        if (!string.IsNullOrWhiteSpace(selectedStore)) message.Headers.Add("X-STORE", selectedStore);
        if (cookie is not null) message.Headers.TryAddWithoutValidation("Cookie", cookie);
        if (request.Method != HttpMethod.Get && (request.Method != HttpMethod.Delete || contract.Form))
        {
            if (contract.ClientBasic && authorization?.StartsWith("Basic ") == true && (values.ContainsKey("client_id") || values.ContainsKey("client_secret"))) throw new ConfigurationException("Use Basic or body credentials, never both.");
            message.Content = contract.Form ? EncodeForm(values) : BuildContent(request, values, serializer);
        }
        return message;
    }

    private static HttpContent EncodeForm(JObject values) => new FormUrlEncodedContent(values.Properties().Where(p => p.Value.Type != JTokenType.Null).SelectMany(p => p.Value is JArray array ? array.Select(item => new KeyValuePair<string, string>(p.Name + "[]", item.ToString())) : new[] { new KeyValuePair<string, string>(p.Name, p.Value.ToString()) }));

    private static HttpContent BuildContent(SellAppRequest request, JObject values, JsonSerializer serializer)
    {
        if (request.BodyEncoding == "form-data")
        {
            var multipart = new MultipartFormDataContent();
            foreach (var (name, value) in MultipartValues(request)) AddMultipartValue(multipart, name, value);
            return multipart;
        }
        if (request.BodyEncoding == "form-urlencoded")
        {
            return new FormUrlEncodedContent(values.Properties()
                .Where(property => property.Value.Type != JTokenType.Null)
                .Select(property => new KeyValuePair<string, string>(property.Name, property.Value.ToString())));
        }
        if (request.BodyEncoding == "binary" && request.Options is byte[] bytes)
        {
            return new ByteArrayContent(bytes);
        }
        if (request.BodyEncoding == "text" && request.Options is string text)
        {
            return new StringContent(text, Encoding.UTF8, "text/plain");
        }

        var body = request.BodyParams is null ? values : JObject.FromObject(request.BodyParams, serializer);
        return new StringContent(body.ToString(Formatting.None), Encoding.UTF8, "application/json");
    }

    private static IEnumerable<(string Name, object? Value)> MultipartValues(SellAppRequest request)
    {
        if (request.BodyParams is not null)
        {
            foreach (var pair in request.BodyParams) yield return (pair.Key, pair.Value);
            yield break;
        }
        if (request.Options is null) yield break;

        foreach (var property in request.Options.GetType().GetProperties(BindingFlags.Instance | BindingFlags.Public))
        {
            if (!property.CanRead) continue;
            var jsonProperty = property.GetCustomAttribute<JsonPropertyAttribute>();
            var name = jsonProperty?.PropertyName ?? SnakeCase.GetPropertyName(property.Name, false);
            yield return (name, property.GetValue(request.Options));
        }
    }

    private static void AddMultipartValue(MultipartFormDataContent multipart, string name, object? value)
    {
        if (value is null) return;
        if (value is byte[] bytes)
        {
            multipart.Add(new ByteArrayContent(bytes), name, name);
            return;
        }
        if (value is IEnumerable<byte[]> byteFiles)
        {
            foreach (var fileBytes in byteFiles) multipart.Add(new ByteArrayContent(fileBytes), name, name);
            return;
        }
        if (value is FileInfo file)
        {
            multipart.Add(new ByteArrayContent(File.ReadAllBytes(file.FullName)), name, file.Name);
            return;
        }
        if (value is string path && File.Exists(path))
        {
            multipart.Add(new ByteArrayContent(File.ReadAllBytes(path)), name, Path.GetFileName(path));
            return;
        }
        if (value is Stream stream)
        {
            if (!stream.CanSeek) throw new ConfigurationException("Multipart streams must be seekable for safe retries.");
            var position = stream.Position;
            using var copy = new MemoryStream();
            stream.CopyTo(copy);
            stream.Position = position;
            multipart.Add(new ByteArrayContent(copy.ToArray()), name, name);
            return;
        }
        if (value is System.Collections.IEnumerable values && value is not string)
        {
            foreach (var item in values) AddMultipartValue(multipart, name, item);
            return;
        }
        if (value.GetType().IsPrimitive || value is decimal || value is string || value is Enum)
        {
            multipart.Add(new StringContent(Convert.ToString(value, System.Globalization.CultureInfo.InvariantCulture) ?? string.Empty), name);
            return;
        }

        multipart.Add(new StringContent(JsonConvert.SerializeObject(value, JsonSettings), Encoding.UTF8, "application/json"), name);
    }

    private static bool IsRetryable(HttpStatusCode status) => status is HttpStatusCode.RequestTimeout or HttpStatusCode.Conflict or HttpStatusCode.TooManyRequests || (int)status >= 500;
    private static TimeSpan RetryDelay(HttpResponseMessage? response, int attempt)
    {
        var retryAfter = response?.Headers.RetryAfter;
        var requested = retryAfter?.Delta ?? (retryAfter?.Date - DateTimeOffset.UtcNow);
        var exponential = TimeSpan.FromMilliseconds(Math.Min(8_000, 250 * Math.Pow(2, Math.Min(attempt, 5))));
        var delay = requested ?? exponential + TimeSpan.FromMilliseconds(Random.Shared.NextDouble() * exponential.TotalMilliseconds);
        return delay < TimeSpan.Zero ? TimeSpan.Zero : delay > TimeSpan.FromSeconds(30) ? TimeSpan.FromSeconds(30) : delay;
    }

    private static async Task ThrowApiException(HttpResponseMessage response, CancellationToken ct)
    {
        var raw = await response.Content.ReadAsStringAsync(ct).ConfigureAwait(false);
        JObject? json = null;
        try { json = JObject.Parse(raw); } catch (JsonException) { }
        var error = json?["error"] as JObject ?? json;
        var status = (int)response.StatusCode;
        var message = (error?["message"] ?? error?["error_description"])?.ToString() ?? raw;
        var type = error?["type"]?.ToString();
        var code = (error?["code"] ?? error?["error"])?.ToString();
        var param = error?["param"]?.ToString();
        var requestId = error?["request_id"]?.ToString() ?? (response.Headers.TryGetValues("X-Request-ID", out var ids) ? ids.FirstOrDefault() : null);
        var docsUrl = error?["docs_url"]?.ToString();
        var headers = response.Headers.Concat(response.Content.Headers).ToDictionary(h => h.Key, h => h.Value.ToArray(), StringComparer.OrdinalIgnoreCase);
        var exception = status switch
        {
            400 => new BadRequestException(message, status, type, code, param, requestId, docsUrl),
            401 => new AuthenticationException(message, status, type, code, param, requestId, docsUrl),
            403 => new AuthorizationException(message, status, type, code, param, requestId, docsUrl),
            404 => new NotFoundException(message, status, type, code, param, requestId, docsUrl),
            409 => new ConflictException(message, status, type, code, param, requestId, docsUrl),
            422 => new UnprocessableEntityException(message, status, type, code, param, requestId, docsUrl),
            429 => new RateLimitExceededException(message, status, type, code, param, requestId, docsUrl),
            >= 500 => new ServerException(message, status, type, code, param, requestId, docsUrl),
            _ => new ApiException(message, status, type, code, param, requestId, docsUrl),
        };
        exception.Headers = headers;
        exception.RawBody = raw;
        throw exception;
    }

    public void Dispose() { if (ownsHttp) http.Dispose(); GC.SuppressFinalize(this); }
}

public static class SellAppConfiguration
{
    private static SellAppClient? client;
    public static SellAppClient SellAppClient => client ??= new SellAppClient();
    public static void Configure(SellAppClient value) => client = value;
}
